<?= $this->section('title') ?><?= $record ? 'Editar material' : 'Nuevo material' ?><?= $this->endSection() ?>
<?= $this->section('main') ?>
<div class="card border-0 shadow-sm mx-auto app-wide-form-card"><div class="card-body p-4"><div class="d-flex justify-content-between align-items-center mb-4"><h1 class="h4 mb-0"><?= $record ? 'Editar material' : 'Nuevo material' ?></h1><a class="btn btn-sm btn-outline-secondary" href="<?= url_to('materials') ?>">Volver</a></div><?= $this->include('partials/flash') ?>
<?php if ($categories === [] || $units === []): ?><div class="alert alert-warning">Debes tener al menos una categoría y una unidad activas antes de guardar materiales.</div><?php endif ?>
<form method="post" action="<?= $record ? url_to('materials-update', $record['id']) : url_to('materials-create') ?>"><?= csrf_field() ?><div class="row g-3"><div class="col-md-4"><label class="form-label" for="code">Código</label><input class="form-control" id="code" name="code" value="<?= esc(old('code') ?: ($record['code'] ?? '')) ?>" maxlength="40" pattern="[A-Za-z0-9.-]+" required></div><div class="col-md-8"><label class="form-label" for="name">Nombre</label><input class="form-control" id="name" name="name" value="<?= esc(old('name') ?: ($record['name'] ?? '')) ?>" maxlength="160" required></div><div class="col-md-6"><label class="form-label" for="category_id">Categoría</label><select class="form-select" id="category_id" name="category_id" required><option value="">Selecciona...</option><?php foreach ($categories as $category): ?><option value="<?= esc((string) $category['id']) ?>" <?= (string) old('category_id', (string) ($record['category_id'] ?? '')) === (string) $category['id'] ? 'selected' : '' ?>><?= esc($category['name']) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label" for="unit_id">Unidad de medida</label><select class="form-select" id="unit_id" name="unit_id" required><option value="">Selecciona...</option><?php foreach ($units as $unit): ?><option value="<?= esc((string) $unit['id']) ?>" <?= (string) old('unit_id', (string) ($record['unit_id'] ?? '')) === (string) $unit['id'] ? 'selected' : '' ?>><?= esc($unit['name']) ?> (<?= esc($unit['symbol']) ?>)</option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label" for="minimum_stock">Stock mínimo</label><input class="form-control" type="number" id="minimum_stock" name="minimum_stock" value="<?= esc(old('minimum_stock') ?: ($record['minimum_stock'] ?? '0')) ?>" min="0" max="99999999999.999" step="0.001" required></div><div class="col-md-6 d-flex align-items-end"><div class="form-check mb-2"><input type="hidden" name="allows_fraction" value="0"><input class="form-check-input" type="checkbox" id="allows_fraction" name="allows_fraction" value="1" <?= (string) old('allows_fraction', (string) ($record['allows_fraction'] ?? '0')) === '1' ? 'checked' : '' ?>><label class="form-check-label" for="allows_fraction">Permitir cantidades fraccionarias</label></div></div><div class="col-12"><label class="form-label" for="description">Descripción</label><textarea class="form-control" id="description" name="description" rows="3" maxlength="1000"><?= esc(old('description') ?: ($record['description'] ?? '')) ?></textarea></div></div><button class="btn btn-primary mt-4" type="submit" <?= $categories === [] || $units === [] ? 'disabled' : '' ?>>Guardar</button></form>
</div></div>
